declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }

 $s=$id?one('SELECT * FROM '.table('services').' WHERE id=?',[$id]):[];if($id&&!$s){echo '<div class="notice error">Service not found.</div>';admin_foot();exit;}$s=$s?:['title'=>'','slug'=>'','summary'=>'','body'=>'','icon'=>'monitor','sort_order'=>0,'active'=>1];?><form method="post" class="admin-card editor-single" action="<?=esc(admin_url('service',['id'=>$id]))?>"><?php admin_action('service_save');?><input type="hidden" name="id" value="<?=$id?>"><div class="field-grid"><?php admin_input('title','Service title',$s['title'],'text','required maxlength="120"');admin_input('slug','URL slug',$s['slug'],'text','maxlength="100"');?></div><?php admin_textarea('summary','Short introduction',$s['summary'],3,2000);admin_textarea('body','Service description',str_replace('\\n',"\n",$s['body']),8,16000);?><div class="field-grid"><?php admin_select('icon','Icon',['monitor'=>'Monitor','code'=>'Code','bag'=>'Shopping bag','diamond'=>'Diamond','gear'=>'Gear','growth'=>'Growth','shield'=>'Shield','globe'=>'Globe','layers'=>'Layers'],$s['icon']);admin_input('sort_order','Display order',$s['sort_order'],'number','min="-9999" max="9999"');?></div><?php admin_check('active','Show this service publicly',$s['active']);?><button class="btn gold">Save Service →</button></form><?php if($id):?><form class="delete-form" method="post" action="<?=esc(admin_url('service',['id'=>$id]))?>" data-confirm="Delete this service? Existing inquiry records will remain unchanged."><?php admin_action('service_delete');?><input type="hidden" name="id" value="<?=$id?>"><button class="btn danger small">Delete Service</button></form><?php endif;
